"""Combined Currency Atlas dashboard: UI, cursor interaction, prediction and statistics."""
from fastapi.responses import HTMLResponse, Response
from backend.main import app, ROOT

ANALYTICS = r'''<section id="statistical-analysis" style="padding:80px 9%;background:#fff8df"><div style="display:flex;justify-content:space-between;gap:24px;align-items:end;flex-wrap:wrap"><div><p class="ey">STATISTICAL ANALYSIS</p><h2 style="margin-bottom:8px">Beyond the prediction.</h2><p style="color:#777;max-width:520px;line-height:1.6">Descriptive statistics and volatility indicators calculated from the uploaded historical currency dataset.</p></div><span id="stats-status" class="ey">LOADING DATA…</span></div><div id="stats-cards" style="display:grid;grid-template-columns:repeat(4,minmax(145px,1fr));gap:14px;margin-top:28px"></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px"><div style="background:white;padding:24px;border:1px solid #e8e3d5"><p class="ey">MOST VOLATILE CURRENCIES</p><div id="volatility-list"></div></div><div style="background:white;padding:24px;border:1px solid #e8e3d5"><p class="ey">SELECTED CURRENCY SUMMARY</p><div id="selected-summary" style="color:#555;line-height:2"></div></div></div></section>'''

STYLES = r'''<style>@media(max-width:700px){#stats-cards{grid-template-columns:1fr 1fr!important}#statistical-analysis>div:nth-of-type(2){grid-template-columns:1fr!important}}@media(pointer:fine){body,a,button,select,.row{cursor:none}.atlas-dot,.atlas-ring{position:fixed;top:0;left:0;z-index:99;pointer-events:none;border-radius:50%}.atlas-dot{width:9px;height:9px;margin:-4px;background:#191914}.atlas-ring{width:34px;height:34px;margin:-17px;border:1px solid #c99813;transition:all .2s}.atlas-hover .atlas-dot{background:#f6c542}.atlas-hover .atlas-ring{width:48px;height:48px;margin:-24px;background:#f6c54233}.btn,.download{transition:transform .2s,box-shadow .2s}.btn:hover,.download:hover{transform:translateY(-3px);box-shadow:0 10px 20px #19191430}}</style>'''

SCRIPT = r'''<script>(()=>{if(matchMedia('(pointer:fine)').matches){let d=document.createElement('i'),r=document.createElement('i');d.className='atlas-dot';r.className='atlas-ring';document.body.append(d,r);let x=-50,y=-50,X=-50,Y=-50;addEventListener('mousemove',e=>{x=e.clientX;y=e.clientY;d.style.transform=`translate(${x}px,${y}px)`});(function f(){X+=(x-X)*.16;Y+=(y-Y)*.16;r.style.transform=`translate(${X}px,${Y}px)`;requestAnimationFrame(f)})();document.querySelectorAll('a,button,select,.row').forEach(e=>{e.onmouseenter=()=>document.body.classList.add('atlas-hover');e.onmouseleave=()=>document.body.classList.remove('atlas-hover')})}let stats=[];const money=n=>n<.1?Number(n).toFixed(4):Number(n).toFixed(2);function card(label,value,sub=''){return `<div style="background:white;border:1px solid #e8e3d5;padding:18px"><small style="color:#999;letter-spacing:1px">${label}</small><strong style="display:block;font-size:25px;margin:8px 0">${value}</strong><small style="color:#777">${sub}</small></div>`}function render(){if(!stats.length)return;let s=stats[0],volatile=[...stats].sort((a,b)=>b.volatility_pct-a.volatility_pct);document.querySelector('#stats-status').textContent=`${stats.length} CURRENCIES ANALYZED`;document.querySelector('#stats-cards').innerHTML=card('RECORDS ANALYZED',stats.reduce((n,x)=>n+x.observations,0),'historical observations')+card('HIGHEST VOLATILITY',volatile[0].currency,volatile[0].volatility_pct.toFixed(2)+'% standard deviation')+card('AVG. FORECAST',money(stats.reduce((n,x)=>n+x.forecast,0)/stats.length),'model projection')+card('MOST OBSERVED',stats.sort((a,b)=>b.observations-a.observations)[0].currency,'largest sample');document.querySelector('#volatility-list').innerHTML=volatile.slice(0,5).map(x=>`<p style="border-bottom:1px solid #eee;padding:8px 0;margin:0;display:flex;justify-content:space-between"><b>${x.currency}</b><span>${x.volatility_pct.toFixed(2)}% volatility</span></p>`).join('');document.querySelector('#selected-summary').innerHTML=`<b>${s.currency}</b><br>Mean: $${money(s.mean)} · Median: $${money(s.median)}<br>Range: $${money(s.minimum)} — $${money(s.maximum)}<br>Standard deviation: ${money(s.std_dev)}<br>Prediction: $${money(s.forecast)}`};fetch('/statistics').then(r=>r.ok?r.json():Promise.reject()).then(x=>{stats=x;render()}).catch(()=>{document.querySelector('#stats-status').textContent='DATASET REQUIRED';document.querySelector('#selected-summary').textContent='Start the API with cleaned_currency_data.csv in the project root to calculate live statistics.'})})();</script>'''

@app.get('/', include_in_schema=False)
def dashboard() -> HTMLResponse:
    page = (ROOT / 'index.html').read_text(encoding='utf-8')
    page = page.replace('<div class="cta">', ANALYTICS + '<div class="cta">')
    return HTMLResponse(page.replace('</body>', STYLES + SCRIPT + '</body>'))

@app.get('/cursor-enhancements.js', include_in_schema=False)
def cursor_script() -> Response:
    return Response((ROOT / 'cursor-enhancements.js').read_text(encoding='utf-8'), media_type='application/javascript')
